import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.seoConfiguration().getSeoConfiguration();
Map<?, ?> configuration = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("seo_configuration");
Map<?, ?> globalStoreSettings = (Map<?, ?>) configuration.get("global_store_settings");
Map<?, ?> urlSettings = (Map<?, ?>) configuration.get("url_settings");
System.out.println(globalStoreSettings.get("store_name") + " " + globalStoreSettings.get("title_separator"));
System.out.println(urlSettings.get("regenerate_url_on_item_update") + " " + urlSettings.get("auto_redirect_on_url_change"));
for (Object row : (List<?>) ((Map<?, ?>) urlSettings.get("redirects")).get("items")) {
    Map<?, ?> redirect = (Map<?, ?>) row;
    System.out.println(redirect.get("id") + " " + redirect.get("source_url") + " -> " + redirect.get("destination_url"));
}

